export const DECOMPOSING_PROBLEMS_ACTIVITIES = [
{n:1,type:"mcq",micro:"Mengapa memecah masalah",q:"Mengapa memecah masalah besar menjadi bagian-bagian kecil sering membantu?",options:["Karena tiap bagian kecil lebih mudah dipahami dan dikerjakan satu per satu","Karena bagian kecil bisa dilewati, jadi pekerjaan kita menjadi jauh lebih sedikit","Karena masalah tampak lebih rumit sehingga orang lain tak berani mengganggu kita"],answer:0,explain:"Masalah besar terasa berat karena kita mencoba memikirkan semuanya sekaligus. Bagian kecil bisa diselesaikan satu demi satu.",hint:"Lebih mudah memakan sepiring nasi sesuap demi sesuap atau sekaligus?"},
{n:2,type:"mcq",micro:"Contoh dekomposisi",q:"Tugas 'membersihkan seluruh kamar' bisa dipecah menjadi...",options:["Menunggu kamar bersih dengan sendirinya, lalu menikmati hasilnya sambil santai","Merapikan tempat tidur, membereskan meja, menyapu lantai, menata buku","Satu langkah besar saja: bersihkan semuanya sekaligus tanpa dibagi-bagi"],answer:1,explain:"Memecah tugas besar menjadi daftar langkah konkret membuat kita tahu harus mulai dari mana.",hint:"Bagian-bagian apa saja yang membentuk 'kamar bersih'?"},
{n:3,type:"tf",micro:"Bagian kecil bisa dikerjakan terpisah",q:"Benar atau Salah: Setelah masalah dipecah, sebagian bagian sering bisa dikerjakan oleh orang berbeda pada waktu yang sama.",answer:true,explain:"Dekomposisi memungkinkan pembagian tugas: beberapa bagian bisa berjalan paralel sehingga lebih cepat selesai.",hint:"Kalau kamar dipecah jadi 4 tugas, bisakah 4 orang mengerjakannya bersamaan?"},
{n:4,type:"mcq",micro:"Langkah pertama",q:"Kamu diminta membuat mading kelas. Langkah pertama dalam memecah tugas ini sebaiknya...",options:["Menyerah karena tugas membuat mading terlalu besar untuk murid sekolah dasar","Langsung menempel apa saja yang ada di tangan tanpa merencanakan bagiannya dulu","Menuliskan bagian-bagian pekerjaan: tema, isi tulisan, gambar, tata letak, bahan"],answer:2,explain:"Menuliskan daftar bagian mengubah tugas kabur menjadi rencana yang bisa dikerjakan.",hint:"Sebelum bekerja, buat peta pekerjaannya dulu."},
{n:5,type:"mcq",micro:"Sub-masalah",q:"Bagian kecil hasil pemecahan sebuah masalah disebut...",options:["Sub-masalah (bagian dari masalah utama)","Masalah baru yang tidak berhubungan","Solusi akhir"],answer:0,explain:"Sub-masalah adalah potongan dari masalah besar. Menyelesaikan semua sub-masalah berarti menyelesaikan masalah utama.",hint:"Awalan 'sub-' berarti 'bagian dari'."},
{n:6,type:"tf",micro:"Semua bagian harus selesai",q:"Benar atau Salah: Kalau sebagian besar sub-masalah sudah selesai, masalah utama pasti sudah beres meski ada satu bagian penting yang terlewat.",answer:false,explain:"Kalau satu bagian penting terlewat, masalah utama biasanya belum tuntas — seperti kamar yang lantainya belum disapu meski bagian lain sudah rapi.",hint:"Bisakah kamar disebut 'bersih' kalau satu sudut masih berantakan?"},
{n:7,type:"mcq",micro:"Memecah pertanyaan",q:"Pertanyaan besar 'Bagaimana caraku menabung untuk sepeda?' bisa dipecah menjadi pertanyaan kecil seperti...",options:["'Sepeda warna apa yang paling bagus dan paling disukai oleh semua teman di sekolah kita nanti?'","'Berapa harganya? Berapa uangku sekarang? Berapa yang bisa kutabung tiap minggu? Berapa lama?'","'Apakah sepeda itu benar-benar penting, atau lebih baik uangnya dibelikan barang lain saja?'"],answer:1,explain:"Memecah pertanyaan besar menjadi pertanyaan-pertanyaan kecil yang bisa dijawab satu per satu membuatnya bisa dikerjakan.",hint:"Informasi apa saja yang kamu butuhkan untuk menjawab pertanyaan besar itu?"},
{n:8,type:"order",micro:"Memecah tugas memasak",q:"Urutkan bagian-bagian tugas 'membuat nasi goreng' dari yang paling awal.",items:["Menyiapkan bahan (nasi, telur, bumbu, sayur)","Menumis bumbu lalu memasukkan nasi dan bahan lain","Menyajikan di piring","Mencuci alat masak"],answer:[0,1,2,3],explain:"Tugas besar dipecah menjadi urutan langkah: siapkan → masak → sajikan → bereskan.",hint:"Kamu tidak bisa menumis sebelum bahan siap."},
{n:9,type:"mcq",micro:"Bagian yang bergantung",q:"Saat membuat mading: 'mendesain tata letak' baru bisa dilakukan setelah...",options:["Tidak bergantung pada tulisan atau gambar","Mading sudah dipajang di dinding kelas","Isi tulisan dan gambar sudah terkumpul"],answer:2,explain:"Beberapa sub-masalah bergantung pada yang lain. Mengenali urutan ketergantungan membantu menyusun rencana.",hint:"Kamu perlu tahu apa yang akan ditata sebelum menatanya."},
{n:10,type:"mcq",micro:"Bagian yang bebas",q:"Dalam menyiapkan pesta kelas, tugas 'membuat undangan' dan 'menyiapkan daftar lagu' ...",options:["Bisa dikerjakan bersamaan karena tidak saling bergantung","Tidak perlu dikerjakan karena pesta bisa tanpa undangan","Harus berurutan karena lagu dibuat setelah undangan terkirim"],answer:0,explain:"Sub-masalah yang tidak saling bergantung bisa dikerjakan paralel, menghemat waktu.",hint:"Apakah salah satu tugas butuh hasil dari tugas lainnya?"},
{n:11,type:"mcq",micro:"Terlalu besar untuk dimulai",q:"Ketika sebuah tugas terasa 'terlalu besar sampai bingung mau mulai dari mana', tanda yang paling berguna adalah...",options:["Tanda bahwa tugas itu mustahil dikerjakan, sehingga tidak perlu dicoba lagi","Tanda bahwa tugas itu perlu dipecah menjadi langkah yang lebih kecil","Tanda bahwa kamu harus menyerah dan meminta orang lain mengerjakannya"],answer:1,explain:"Rasa kewalahan sering berarti masalahnya belum dipecah cukup kecil.",hint:"Apa yang biasanya membuat tugas besar terasa bisa dikerjakan?"},
{n:12,type:"tf",micro:"Memecah butuh waktu di awal",q:"Benar atau Salah: Meluangkan waktu untuk memecah masalah di awal selalu membuang waktu dan sebaiknya dilewati.",answer:false,explain:"Waktu untuk merencanakan pemecahan biasanya terbayar: pekerjaan jadi lebih terarah dan lebih sedikit yang terlewat.",hint:"Apakah membuat daftar belanja sebelum ke pasar itu buang waktu?"},
{n:13,type:"mcq",micro:"Bagian sekecil apa",q:"Sebuah sub-masalah dipecah cukup kecil ketika...",options:["Namanya terdengar rumit dan panjang, sehingga orang mengira kamu bekerja keras","Butuh berhari-hari dikerjakan tanpa henti, sehingga bagian itu sudah cukup besar","Kamu bisa membayangkan dengan jelas langkah nyata untuk menyelesaikannya"],answer:2,explain:"Ukuran yang pas: kecil sampai kamu tahu persis tindakan pertama yang harus dilakukan.",hint:"Kalau kamu masih bingung 'lalu apa', bagian itu masih terlalu besar."},
{n:14,type:"mcq",micro:"Peta pikiran",q:"Salah satu cara menggambar hasil pemecahan masalah adalah dengan...",options:["Membuat diagram pohon: masalah utama di atas, cabang-cabang sub-masalah di bawahnya","Menutup mata lalu menebak bagiannya, sebab gambar dianggap tidak diperlukan","Menghafalkan semua bagiannya di kepala tanpa menuliskan atau menggambarnya"],answer:0,explain:"Diagram pohon atau peta pikiran menunjukkan bagaimana sub-masalah terhubung ke masalah utama.",hint:"Bentuk apa yang menunjukkan 'satu hal terbagi menjadi banyak bagian'?"},
{n:15,type:"mcq",micro:"Contoh sub-masalah proyek sains",q:"Proyek 'menanam kacang hijau dan mengamati pertumbuhannya' bisa dipecah menjadi...",options:["Satu langkah saja: menanam biji, lalu menunggu sampai tumbuh dan selesai dengan sendirinya","Menyiapkan wadah & media, menanam biji, menyiram rutin, mencatat tinggi tiap hari, membuat kesimpulan","Menyiram tanaman sesukanya, menunggu hasil tanpa mencatat, lalu menyimpulkan dari ingatan"],answer:1,explain:"Proyek yang tampak sederhana pun terdiri dari beberapa sub-tugas yang masing-masing perlu direncanakan.",hint:"Apa saja yang harus kamu lakukan dari hari pertama sampai laporan selesai?"},
{n:16,type:"tf",micro:"Bagian bisa dipecah lagi",q:"Benar atau Salah: Setelah masalah dipecah satu kali, sub-masalahnya tidak boleh dipecah lagi meskipun masih terasa besar.",answer:false,explain:"Dekomposisi boleh bertingkat: sub-masalah yang masih besar dipecah menjadi sub-sub-masalah sampai semuanya jelas dan bisa dikerjakan.",hint:"Kalau 'membuat isi mading' masih terasa besar, apa yang bisa kamu lakukan?"},
{n:17,type:"mcq",micro:"Fokus satu bagian",q:"Manfaat mengerjakan satu sub-masalah pada satu waktu adalah...",options:["Pekerjaan jadi lebih lama tanpa alasan jelas, tetapi hasilnya tetap sama","Bagian lain jadi hilang dan terlupakan, sehingga pekerjaan menjadi ringan","Perhatian tidak terpecah, sehingga tiap bagian dikerjakan lebih baik"],answer:2,explain:"Fokus pada satu bagian mengurangi kebingungan dan kesalahan dibanding memikirkan semua sekaligus.",hint:"Lebih mudah menyelesaikan satu teka-teki atau lima teka-teki sekaligus?"},
{n:18,type:"mcq",micro:"Melacak kemajuan",q:"Setelah memecah tugas menjadi daftar, mencentang bagian yang selesai berguna untuk...",options:["Melihat kemajuan dengan jelas dan tahu apa yang masih tersisa","Menghias daftar agar terlihat penuh dan lebih menarik dilihat","Membuat daftar terlihat penuh coretan dan sulit dibaca lagi"],answer:0,explain:"Daftar sub-tugas yang bisa dicentang mengubah kemajuan yang samar menjadi terlihat, dan menjaga semangat.",hint:"Bagaimana kamu tahu 'tinggal 2 bagian lagi'?"},
{n:19,type:"mcq",micro:"Dekomposisi vs melompat",q:"Perbedaan antara 'memecah dulu lalu mengerjakan' dan 'langsung mengerjakan apa yang terlintas' adalah...",options:["Tidak ada bedanya, karena hasil pekerjaan keduanya akan sama dan sama rapinya","Memecah dulu membuat pekerjaan lebih terarah dan mengurangi bagian yang terlupakan","Mengerjakan langsung membuat pekerjaan lebih cepat dan hasilnya lebih baik"],answer:1,explain:"Langsung mengerjakan tanpa peta sering membuat sebagian pekerjaan terlewat atau harus diulang.",hint:"Apa risiko mengerjakan tugas besar tanpa daftar?"},
{n:20,type:"open",micro:"Memecah tugasmu sendiri",q:"Pilih satu tugas atau proyek yang sedang atau akan kamu kerjakan. Pecah menjadi minimal 4 sub-tugas, dan tandai mana yang bisa dikerjakan bersamaan dan mana yang harus berurutan.",explain:"Jawaban baik menyebut sub-tugas konkret DAN mengenali ketergantungan antar bagian.",hint:"Buat daftar dulu, lalu tarik panah 'harus setelah' antar bagian.",sample:"Contoh — Tugas: membuat presentasi tentang hewan langka. Sub-tugas: (1) pilih hewan & kumpulkan fakta, (2) buat kerangka slide, (3) cari/gambar ilustrasi, (4) susun slide, (5) latihan bicara. Urutan: (1) harus sebelum (2) dan (3); (2) dan (3) bisa bersamaan; (4) setelah (2) dan (3); (5) terakhir."},
{n:21,type:"mcq",micro:"Membaca pohon masalah",q:"Dalam diagram pohon masalah, apa arti sebuah kotak yang punya beberapa cabang di bawahnya?",options:["Bagian itu sudah selesai dikerjakan dan tidak perlu diperiksa lagi","Kotak itu tidak penting, jadi cabang di bawahnya boleh dihapus dari diagram","Bagian itu masih bisa dipecah menjadi sub-bagian yang lebih kecil"],answer:2,explain:"Cabang di bawah sebuah kotak menunjukkan sub-masalah dari kotak tersebut.",hint:"Cabang ke bawah = 'terdiri dari'."},
{n:22,type:"mcq",micro:"Daun pohon",q:"Kotak paling bawah pada pohon masalah (tanpa cabang lagi) sebaiknya berupa...",options:["Tugas kecil dan jelas yang bisa langsung dikerjakan","Nama masalah utama yang dituliskan ulang di bawah","Tugas yang masih kabur dan besar, belum jelas langkahnya"],answer:0,explain:"Ujung-ujung pohon adalah tindakan konkret. Kalau masih kabur, berarti perlu satu cabang lagi.",hint:"Bagian terkecil harus bisa langsung kamu kerjakan tanpa bingung."},
{n:23,type:"mcq",micro:"Bekerja mundur dari tujuan",q:"'Bekerja mundur' berarti memecah masalah dengan cara...",options:["Berjalan mundur secara fisik sambil mengerjakan tugas, supaya otak lebih mudah berpikir tentang masalahnya","Mulai dari keadaan tujuan, lalu bertanya 'apa yang harus terjadi tepat sebelum ini?' berulang kali","Mengerjakan langkah terakhir lebih dulu tanpa memikirkan apa yang harus terjadi sebelum langkah itu"],answer:1,explain:"Bekerja mundur dari tujuan sering memunculkan langkah-langkah yang tidak terlihat saat berpikir maju.",hint:"Kalau tujuannya 'kue matang di meja', apa yang harus terjadi persis sebelumnya?"},
{n:24,type:"mcq",micro:"Tonggak (milestone)",q:"'Tonggak' dalam sebuah rencana adalah...",options:["Batu penanda di pinggir jalan supaya pengendara tahu jarak ke tujuan","Hukuman bagi anggota kelompok yang terlambat menyelesaikan bagiannya","Titik pencapaian penting yang menandai sebagian pekerjaan sudah beres"],answer:2,explain:"Tonggak adalah penanda kemajuan besar, misalnya 'semua bahan terkumpul' atau 'draf pertama selesai'.",hint:"Bukan tugas kecil, tapi 'kita sudah sampai di titik ini'."},
{n:25,type:"mcq",micro:"Ketergantungan",q:"Jika tugas B tidak bisa dimulai sebelum tugas A selesai, kita katakan B...",options:["Bergantung pada A","Sama dengan A","Bebas dari A"],answer:0,explain:"Ketergantungan menentukan urutan. Tugas yang bergantung harus menunggu tugas yang dibutuhkannya.",hint:"B butuh hasil A dulu — B ... pada A."},
{n:26,type:"classify",micro:"Bagian yang bergantung vs bebas",q:"Untuk proyek 'membuat film pendek kelas', kelompokkan tiap pasangan sebagai 'Harus berurutan' atau 'Bisa bersamaan'.",items:["Menulis naskah, lalu syuting adegan","Membuat poster film, dan merekam musik latar","Syuting semua adegan, lalu menyunting video","Menyiapkan kostum, dan mencari lokasi syuting"],groups:["Harus berurutan","Bisa bersamaan"],answer:{"Harus berurutan":["Menulis naskah, lalu syuting adegan","Syuting semua adegan, lalu menyunting video"],"Bisa bersamaan":["Membuat poster film, dan merekam musik latar","Menyiapkan kostum, dan mencari lokasi syuting"]},explain:"Tugas yang butuh hasil tugas lain harus berurutan; tugas yang mandiri bisa jalan paralel.",hint:"Tanya: apakah tugas kedua butuh hasil tugas pertama?"},
{n:27,type:"tf",micro:"Jalur kritis",q:"Benar atau Salah: Rantai tugas berurutan yang paling panjang menentukan waktu tercepat sebuah proyek bisa selesai.",answer:true,explain:"Rantai terpanjang dari tugas yang saling bergantung disebut 'jalur kritis'. Proyek tidak bisa lebih cepat dari itu, sepintar apa pun pembagian tugas lain.",hint:"Kalau satu rantai butuh 10 hari berurutan, bisakah proyek selesai dalam 6 hari?"},
{n:28,type:"mcq",micro:"Memecah berdasarkan bagian fisik",q:"Salah satu cara memecah masalah 'merancang taman sekolah' adalah membaginya berdasarkan...",options:["Hari dalam seminggu: bagian Senin, Selasa, dan seterusnya","Area: pintu masuk, area duduk, kebun, jalan setapak","Warna favorit siswa: bagian merah, biru, dan hijau"],answer:1,explain:"Memecah berdasarkan bagian nyata (area, komponen, ruang) adalah cara alami untuk banyak masalah desain.",hint:"Bagian-bagian nyata apa yang menyusun sebuah taman?"},
{n:29,type:"mcq",micro:"Memecah berdasarkan tahap waktu",q:"Cara lain memecah masalah adalah berdasarkan tahap: 'sebelum', 'saat', dan 'sesudah'. Ini cocok untuk masalah seperti...",options:["Mengeja sebuah kata panjang huruf demi huruf dengan benar","Menghitung hasil dari 12 x 8 secara cepat di kepala","Menyelenggarakan lomba (persiapan, hari lomba, evaluasi)"],answer:2,explain:"Masalah berupa acara atau proses sering paling mudah dipecah berdasarkan urutan waktu.",hint:"Kegiatan mana yang punya 'sebelum, saat, sesudah' yang jelas?"},
{n:30,type:"order",micro:"Bekerja mundur dari tujuan",q:"Tujuan: 'Tepat pukul 07.00 aku sudah duduk di kelas.' Urutkan langkah hasil bekerja mundur, dari yang paling akhir ke paling awal.",items:["Pukul 07.00 duduk di kelas","Pukul 06.45 tiba di sekolah","Pukul 06.20 berangkat dari rumah","Pukul 05.45 bangun dan bersiap"],answer:[0,1,2,3],explain:"Bekerja mundur: dari 'duduk di kelas' kita telusuri mundur — tiba di sekolah, berangkat, bangun — sehingga jam bangun ditemukan.",hint:"Mulai dari tujuan, mundur satu langkah setiap kali."},
{n:31,type:"mcq",micro:"Memecah agar bisa dibagi",q:"Kelompokmu berlima harus membuat kliping 20 artikel dalam seminggu. Cara memecah yang paling adil dan efisien:",options:["Bagi 20 artikel menjadi 5 bagian, masing-masing 4 artikel","Kerjakan bersama satu artikel setiap kali sampai semuanya selesai","Satu orang mengerjakan semua artikel, empat lainnya menunggu hasilnya"],answer:0,explain:"Memecah tugas menjadi bagian setara yang bisa dikerjakan mandiri memungkinkan kerja paralel dan pembagian yang jelas.",hint:"Bagaimana agar kelima orang bisa bekerja pada saat yang sama?"},
{n:32,type:"mcq",micro:"Bagian yang terlewat",q:"Tim membuat daftar sub-tugas pesta tapi lupa 'membereskan setelah acara'. Akibat paling mungkin:",options:["Tidak ada akibat, karena acara yang sudah selesai tidak memerlukan pekerjaan lagi","Di akhir acara semua bingung dan ruangan berantakan karena tak ada yang bertanggung jawab","Pesta jadi lebih meriah karena ruangan yang berantakan membuat tamu semakin betah"],answer:1,explain:"Sub-tugas yang terlewat saat dekomposisi sering menjadi masalah di kemudian hari. Memeriksa kelengkapan itu penting.",hint:"Apa yang terjadi kalau satu bagian penting tidak ada dalam daftar?"},
{n:33,type:"tf",micro:"Dekomposisi membantu memperkirakan waktu",q:"Benar atau Salah: Menebak waktu keseluruhan sebuah proyek sekaligus biasanya lebih akurat daripada memperkirakan tiap sub-tugas lalu menjumlahkannya.",answer:false,explain:"Justru sebaliknya: perkiraan per bagian lebih mudah dan lebih akurat; menjumlahkannya memberi gambaran total yang lebih dapat dipercaya daripada satu tebakan besar.",hint:"Lebih mudah menebak lama '1 slide' atau lama 'seluruh presentasi'?"},
{n:34,type:"mcq",micro:"Bagian yang paling berisiko",q:"Setelah memecah proyek, berguna menandai sub-tugas yang paling sulit atau paling tidak pasti supaya...",options:["Bisa diberikan kepada anggota yang kurang peduli, supaya anggota lain tidak terbebani","Bisa dilewatkan dengan cara tidak dikerjakan, sehingga proyek tetap dianggap selesai","Bisa dikerjakan atau diuji lebih awal, saat masih ada waktu untuk memperbaiki bila bermasalah"],answer:2,explain:"Mengerjakan bagian berisiko lebih dulu mengurangi kejutan buruk di akhir proyek.",hint:"Kapan waktu terbaik menemukan bahwa sesuatu tidak berhasil — awal atau akhir?"},
{n:35,type:"mcq",micro:"Menggabungkan kembali",q:"Setelah semua sub-masalah selesai, langkah yang sering masih dibutuhkan adalah...",options:["Menggabungkan hasil tiap bagian dan memeriksa apakah semuanya cocok menjadi satu kesatuan","Langsung menganggap proyek selesai tanpa memeriksa apakah semua bagian benar-benar cocok satu sama lain","Memulai proyek dari awal lagi dengan membuang semua hasil bagian yang sudah dikerjakan sebelumnya"],answer:0,explain:"Bagian-bagian yang dikerjakan terpisah perlu disatukan dan diperiksa kesesuaiannya — jahitan antar bagian sering perlu dirapikan.",hint:"Potongan puzzle yang sudah jadi masih perlu apa?"},
{n:36,type:"mcq",micro:"Dekomposisi soal cerita",q:"Soal: 'Ibu membeli 3 kg apel seharga Rp25.000/kg dan 2 kg jeruk seharga Rp20.000/kg. Berapa kembalian dari Rp150.000?' Sub-langkahnya:",options:["Langsung menebak jumlah kembalian tanpa menghitung harga apel dan jeruk","Hitung harga apel, hitung harga jeruk, jumlahkan, lalu kurangkan dari Rp150.000","Hanya menghitung harga apel, lalu menganggap harga jeruk tak perlu dihitung"],answer:1,explain:"Soal cerita bertingkat diselesaikan dengan memecahnya menjadi perhitungan kecil berurutan.",hint:"Informasi antara apa yang perlu kamu cari sebelum bisa menghitung kembalian?"},
{n:37,type:"tf",micro:"Urutan sub-tugas bisa fleksibel",q:"Benar atau Salah: Semua sub-tugas dalam sebuah rencana harus dikerjakan dalam urutan yang tetap, tidak peduli apakah mereka saling bergantung atau tidak.",answer:false,explain:"Hanya tugas yang saling bergantung yang urutannya wajib. Sub-tugas yang mandiri bisa diatur sesuai ketersediaan waktu, alat, atau orang.",hint:"Apakah 'membuat undangan' harus sebelum atau sesudah 'membuat daftar lagu'?"},
{n:38,type:"mcq",micro:"Terlalu banyak bagian",q:"Kalau sebuah tugas kecil dipecah menjadi 50 langkah super rinci, risikonya...",options:["Hasilnya lebih baik karena makin rinci rencana, makin bagus pula pekerjaannya","Tidak ada risiko, karena rencana rinci membuat pekerjaan jauh lebih cepat selesai","Rencana jadi rumit dan malah menghabiskan waktu untuk mengurus daftar, bukan mengerjakan"],answer:2,explain:"Ada keseimbangan: cukup rinci agar jelas, tapi tidak sampai daftar tugasnya sendiri jadi beban.",hint:"Apakah perlu 10 langkah untuk 'menyapu lantai kecil'?"},
{n:39,type:"mcq",micro:"Dekomposisi berulang untuk pekerjaan rutin",q:"Setelah kamu memecah 'menyiapkan tas sekolah' sekali dengan baik, di hari berikutnya kamu bisa...",options:["Memakai daftar yang sama sebagai kebiasaan, tanpa perlu memikirkannya dari nol","Memecahnya lagi dari awal setiap hari dengan berpikir panjang, seakan belum pernah","Melupakan cara sebelumnya dan mengacak isi tas tiap pagi agar tak jadi kebiasaan"],answer:0,explain:"Hasil dekomposisi yang baik untuk tugas berulang bisa menjadi daftar periksa (checklist) tetap.",hint:"Untuk apa membuat rencana yang sama berkali-kali?"},
{n:40,type:"open",micro:"Membuat pohon masalah",q:"Buat pohon masalah (dalam bentuk daftar bertingkat) untuk 'menyiapkan pentas seni kelas'. Masalah utama di tingkat 1, minimal 3 sub-masalah di tingkat 2, dan pecah salah satunya menjadi tingkat 3.",explain:"Jawaban baik menunjukkan masalah utama terbagi menjadi sub-masalah, dan salah satunya terbagi lagi menjadi tugas yang lebih konkret.",hint:"Tingkat paling bawah harus berupa tugas yang bisa langsung dikerjakan.",sample:"1. Pentas seni kelas\n  1.1 Menentukan acara (pilih jenis pertunjukan, susun urutan tampil)\n  1.2 Latihan (jadwal latihan, bagi peran, gladi bersih)\n  1.3 Perlengkapan\n    1.3.1 Panggung & dekorasi\n    1.3.2 Sound & musik\n    1.3.3 Kostum & properti\n  1.4 Penonton & publikasi (undangan, kursi, pembawa acara)"},
{n:41,type:"mcq",micro:"Bagian tidak tumpang tindih",q:"Saat memecah masalah, sebaiknya sub-bagiannya...",options:["Saling tumpang tindih agar aman, sehingga satu pekerjaan dikerjakan banyak orang","Tidak banyak tumpang tindih, sehingga tiap pekerjaan jelas milik satu bagian","Sama persis satu sama lain, sehingga semua anggota mengerjakan hal yang sama"],answer:1,explain:"Bagian yang tumpang tindih membuat kerja ganda dan kebingungan siapa yang bertanggung jawab.",hint:"Kalau dua orang mengira tugas yang sama adalah bagian mereka, apa yang terjadi?"},
{n:42,type:"mcq",micro:"Bagian yang lengkap",q:"Selain tidak tumpang tindih, kumpulan sub-bagian yang baik juga harus...",options:["Sengaja meninggalkan bagian sulit supaya anggota tidak kesulitan bekerja","Hanya mencakup bagian yang menyenangkan agar bagian membosankan dilewati","Mencakup seluruh masalah — tidak ada bagian yang tertinggal di luar"],answer:2,explain:"Dua syarat pemecahan yang baik: tidak tumpang tindih DAN lengkap menutupi seluruh masalah.",hint:"Kalau semua bagian dijumlahkan, apakah hasilnya masalah utuh?"},
{n:43,type:"mcq",micro:"Memilih sumbu pemecahan",q:"Masalah 'meningkatkan kunjungan perpustakaan' bisa dipecah berdasarkan JENIS PENGUNJUNG (kelas bawah / kelas atas / guru) atau berdasarkan HAMBATAN (tidak tahu koleksi / jam buka / suasana). Memilih sumbu pemecahan yang tepat berarti...",options:["Memilih sumbu yang paling membantu menemukan tindakan nyata untuk masalah ini","Memilih sumbu yang pertama terpikir, tanpa menimbang apakah hasilnya membantu","Memilih sumbu yang namanya paling panjang, karena pemecahannya jadi lebih lengkap"],answer:0,explain:"Sumbu pemecahan yang berbeda memunculkan solusi yang berbeda. Pilih yang paling mengarah ke tindakan.",hint:"Sumbu mana yang langsung menyarankan 'apa yang bisa kita perbaiki'?"},
{n:44,type:"mcq",micro:"Dekomposisi fungsional",q:"Memecah 'aplikasi kuis sederhana' menjadi: 'menampilkan soal', 'menerima jawaban', 'memeriksa benar/salah', 'menghitung skor' adalah pemecahan berdasarkan...",options:["Warna tombol dan tampilan layar aplikasi","Fungsi/tugas yang harus dilakukan sistem","Nama pembuat dan tanggal pembuatannya"],answer:1,explain:"Dekomposisi fungsional membagi masalah menjadi 'apa saja yang harus bisa dilakukan'.",hint:"Tiap bagian adalah satu 'pekerjaan' yang dilakukan program."},
{n:45,type:"mcq",micro:"Alokasi sumber daya ke bagian",q:"Setelah memecah proyek dan punya anggaran Rp200.000, langkah masuk akal berikutnya:",options:["Simpan seluruh anggaran dan jangan dipakai, supaya uangnya utuh sampai proyek selesai","Habiskan seluruh anggaran untuk satu bagian saja, sehingga bagian lain tak dapat dana","Bagikan anggaran ke tiap sub-tugas sesuai kebutuhannya, sisakan sedikit cadangan"],answer:2,explain:"Dekomposisi memudahkan alokasi: tiap bagian mendapat porsi waktu, uang, dan orang sesuai kebutuhannya.",hint:"Bagaimana kamu tahu satu bagian tidak menghabiskan jatah bagian lain?"},
{n:46,type:"mcq",micro:"Antarmuka antar bagian",q:"'Titik temu' antara dua sub-tugas — misalnya tim tulisan menyerahkan naskah ke tim tata letak — perlu disepakati di awal karena...",options:["Kalau formatnya tidak cocok (misalnya tulisan terlalu panjang untuk kolom), kedua tim harus mengulang pekerjaan","Supaya proyek terlihat resmi dan rapi di mata guru maupun tim lain yang akan menilai hasil kerja","Tidak penting karena kedua tim bisa menyesuaikan sendiri hasilnya setelah pekerjaan masing-masing selesai"],answer:0,explain:"Bagian yang dikerjakan terpisah bertemu di 'antarmuka'. Menyepakati bentuk serah-terima mencegah pekerjaan ulang.",hint:"Apa yang harus disepakati sebelum satu tim menyerahkan hasil ke tim lain?"},
{n:47,type:"order",micro:"Proses dekomposisi lengkap",q:"Urutkan langkah memecah sebuah masalah besar menjadi rencana kerja.",items:["Nyatakan masalah utama dengan jelas","Pilih sumbu pemecahan dan daftar sub-masalah utamanya","Pecah sub-masalah yang masih besar sampai tiap bagian bisa dikerjakan","Tentukan urutan/ketergantungan dan siapa mengerjakan apa"],answer:[0,1,2,3],explain:"Nyatakan masalah → pilih sumbu & daftar sub-masalah → pecah lebih dalam → susun urutan dan pembagian.",hint:"Kamu perlu tahu masalahnya sebelum bisa memecahnya."},
{n:48,type:"mcq",micro:"Dekomposisi masalah abstrak",q:"Masalah 'aku sulit fokus saat belajar' bisa dipecah menjadi sub-pertanyaan seperti...",options:["'Apakah belajar itu benar-benar perlu dilakukan, atau sebenarnya lebih baik berhenti belajar saja?'","'Kapan aku paling sulit fokus? Di mana? Apa yang mengganggu? Bagaimana kondisi tubuhku (lapar/ngantuk)?'","'Apakah aku ini memang seorang pemalas, sehingga tidak akan pernah bisa fokus saat belajar nanti?'"],answer:1,explain:"Bahkan masalah tentang diri sendiri bisa dipecah menjadi pertanyaan spesifik yang bisa diamati dan ditangani satu per satu.",hint:"Ubah 'sulit fokus' menjadi beberapa pertanyaan 'kapan / di mana / apa'."},
{n:49,type:"mcq",micro:"Bagian bersama",q:"Dua sub-proyek berbeda ternyata sama-sama butuh 'daftar kontak orang tua'. Cara efisien:",options:["Batalkan salah satu sub-proyek","Tiap sub-proyek membuat daftarnya sendiri secara terpisah","Kenali kebutuhan bersama itu, kerjakan sekali, lalu pakai bersama"],answer:2,explain:"Dekomposisi yang teliti memunculkan bagian yang bisa dipakai bersama, menghindari pekerjaan ganda.",hint:"Kalau dua bagian butuh hal yang sama, berapa kali sebaiknya dibuat?"},
{n:50,type:"mcq",micro:"Ukuran bagian dan tenggat",q:"Aturan praktis yang berguna: pecah tugas sampai tiap bagian bisa diselesaikan dalam...",options:["Satu sesi kerja yang wajar (misalnya kurang dari satu atau dua jam untuk pelajar)","Tepat 3 detik kerja saja, sebelum langsung berpindah ke bagian berikutnya","Waktu yang tidak terbatas, asalkan hasil akhirnya terlihat sangat bagus nanti"],answer:0,explain:"Bagian yang muat dalam satu sesi kerja memberi rasa selesai yang sering, menjaga motivasi dan memudahkan penjadwalan.",hint:"Seberapa besar sepotong pekerjaan supaya kamu bisa menyelesaikannya tanpa berhenti kebingungan?"},
{n:51,type:"open",micro:"Memilih sumbu pemecahan",q:"Masalah: 'Sampah di kantin menumpuk setelah istirahat.' Tuliskan DUA cara berbeda memecah masalah ini (dua sumbu berbeda), dan sebutkan satu tindakan yang muncul dari masing-masing.",explain:"Jawaban baik menunjukkan dua pembagian yang benar-benar berbeda dan bagaimana masing-masing mengarah ke solusi berbeda.",hint:"Coba satu sumbu 'berdasarkan jenis' dan satu 'berdasarkan waktu/tahap'.",sample:"Sumbu 1 — berdasarkan jenis sampah: sisa makanan / plastik kemasan / kertas. Tindakan: sediakan 3 tempat sampah terpisah + poster pemilahan. Sumbu 2 — berdasarkan tahap: saat membeli (kemasan berlebih) / saat makan (tidak ada tempat sampah dekat meja) / setelah makan (tidak ada yang membuang). Tindakan: taruh tempat sampah di tiap meja + jadwal piket pengangkutan tiap akhir istirahat."},
{n:52,type:"mcq",micro:"Dekomposisi dan delegasi",q:"Seorang ketua panitia yang sudah memecah acara menjadi 6 bidang jelas bisa...",options:["Membiarkan tiap orang mengerjakan yang disukai tanpa arahan dan pembagian tugas","Menyerahkan tiap bidang ke koordinator dengan tanggung jawab yang jelas","Mengerjakan keenam bidang itu sendirian agar tak perlu repot menjelaskan"],answer:1,explain:"Dekomposisi yang rapi adalah dasar delegasi yang adil: tiap orang tahu persis bagian dan batas tanggung jawabnya.",hint:"Bagaimana pembagian tugas jadi jelas?"},
{n:53,type:"tf",micro:"Bagian tersisa = masalah baru",q:"Benar atau Salah: Jika setelah menyelesaikan semua sub-tugas ternyata masalah utama belum beres, kemungkinan besar ada sub-masalah yang belum dikenali saat pemecahan.",answer:true,explain:"Dekomposisi yang tidak lengkap meninggalkan celah. Meninjau ulang daftar sub-masalah sering menemukan bagian yang terlewat.",hint:"Kalau semua bagian selesai tapi hasilnya belum utuh, apa yang kurang?"},
{n:54,type:"mcq",micro:"Prioritas antar bagian",q:"Kamu punya waktu terbatas dan 5 sub-tugas. Cara memilih mana yang dikerjakan dulu:",options:["Kerjakan yang paling menyenangkan saja lebih dulu, sedangkan yang penting boleh ditinggalkan di akhir","Kerjakan sesuai urutan abjad nama sub-tugasnya, tanpa mempertimbangkan pentingnya bagi hasil akhir","Kerjakan yang paling penting untuk hasil akhir dan/atau yang menghambat tugas lain"],answer:2,explain:"Utamakan bagian yang berdampak besar pada hasil akhir dan bagian yang menjadi syarat bagi tugas lain (agar tidak menghambat).",hint:"Bagian mana yang kalau tertunda akan menghentikan seluruh proyek?"},
{n:55,type:"mcq",micro:"Dekomposisi menemukan bahwa masalah lebih kecil",q:"Setelah memecah 'membuat website kelas', kamu sadar sebenarnya kelas hanya butuh 'satu halaman berisi jadwal dan pengumuman'. Ini menunjukkan dekomposisi juga bisa...",options:["Memperjelas bahwa masalah sebenarnya lebih kecil dari yang dikira","Membuat masalah menjadi lebih besar dan rumit daripada yang kita bayangkan","Tidak mengubah pemahaman kita, karena memecah hanyalah menulis daftar"],answer:0,explain:"Memecah masalah sering mengungkap bahwa hanya sebagian kecil yang benar-benar dibutuhkan.",hint:"Apakah semua bagian 'website' benar-benar diperlukan?"},
{n:56,type:"mcq",micro:"Bagian yang tidak jelas pemiliknya",q:"Dalam daftar sub-tugas, ada bagian 'koordinasi dengan sekolah' yang tidak masuk bidang mana pun. Tindakan terbaik:",options:["Abaikan saja bagian itu karena mungkin tidak penting, dan lihat nanti apakah ada yang mengeluh","Tetapkan secara eksplisit siapa yang bertanggung jawab, atau buat bidang baru untuk itu","Serahkan kepada anggota yang kebetulan mengingatnya, tanpa menetapkan penanggung jawab"],answer:1,explain:"Bagian 'di antara' bidang mudah terlupakan. Menugaskannya secara jelas mencegahnya terbengkalai.",hint:"Apa yang terjadi pada tugas yang 'bukan bagian siapa-siapa'?"},
{n:57,type:"tf",micro:"Dekomposisi bukan sekali jadi",q:"Benar atau Salah: Rencana hasil pemecahan boleh direvisi di tengah jalan bila muncul informasi baru.",answer:true,explain:"Saat mengerjakan, kita sering menemukan bahwa sebuah bagian lebih besar/kecil dari dugaan, atau ada ketergantungan baru. Menyesuaikan rencana itu wajar.",hint:"Apakah peta perjalanan boleh diperbarui kalau ada jalan yang ditutup?"},
{n:58,type:"mcq",micro:"Menguji satu bagian dulu",q:"Sebelum membuat 100 gelang untuk bazar, kamu membuat 5 dulu. Dari sudut dekomposisi, ini adalah...",options:["Melanggar rencana yang sudah dibuat karena mengerjakan hal yang tidak termasuk tugas utama","Membuang bahan secara sia-sia karena lima gelang percobaan itu tidak akan dijual nanti","Mengerjakan versi kecil dari satu sub-tugas untuk menguji cara dan perkiraan waktu sebelum skala penuh"],answer:2,explain:"Mengerjakan sampel kecil dari sebuah sub-tugas memberi informasi (berapa lama, apa kendalanya) sebelum berkomitmen penuh.",hint:"Apa yang kamu pelajari dari membuat 5 gelang pertama?"},
{n:59,type:"mcq",micro:"Dekomposisi masalah kelompok",q:"Konflik: 'Kelompok kami selalu ribut dan tugas tidak selesai.' Pemecahan yang membantu:",options:["'Bagian mana yang macet: pembagian tugas, komunikasi, tenggat, atau kualitas hasil?' lalu tangani bagian itu","'Bubarkan kelompok' lalu kerjakan tugas itu sendiri-sendiri di rumah supaya tidak ada lagi pertengkaran","'Siapa anggota yang paling menyebalkan?' lalu tegur dia di depan seluruh kelompok agar berubah"],answer:0,explain:"Memecah masalah kelompok yang kabur menjadi aspek-aspek konkret membuatnya bisa diperbaiki tanpa saling menyalahkan.",hint:"Ubah 'selalu ribut' menjadi beberapa kemungkinan bagian yang bisa diperiksa."},
{n:60,type:"open",micro:"Rencana kerja dari dekomposisi",q:"Untuk proyek 'kebun mini di pojok kelas', buat rencana kerja: (a) 4–6 sub-tugas, (b) perkiraan waktu tiap sub-tugas, (c) urutan/ketergantungan, (d) tandai satu bagian paling berisiko dan mengapa.",explain:"Rencana baik menyebut sub-tugas konkret, perkiraan waktu, ketergantungan yang benar, dan identifikasi risiko dengan alasan.",hint:"Buat daftar dulu, taruh perkiraan waktu, lalu susun mana sebelum mana.",sample:"Sub-tugas: (1) rancang & ukur area [30 mnt], (2) kumpulkan wadah & tanah [2 hari, menunggu sumbangan], (3) pilih tanaman yang cocok cahaya kelas [1 jam riset], (4) tanam [1 jam], (5) buat jadwal siram & penanggung jawab [20 mnt], (6) buat papan nama tanaman [30 mnt]. Urutan: (1) & (3) bisa paralel; (2) dan (4) setelah (1); (4) setelah (2) dan (3); (5) setelah (4); (6) kapan saja. Paling berisiko: (3) pemilihan tanaman — kalau salah pilih, tanaman mati karena cahaya kelas kurang; uji dengan 1–2 tanaman dulu."},
{n:61,type:"mcq",micro:"Ketika bagian tidak bisa dipisah",q:"Beberapa masalah punya bagian yang sangat saling terkait sehingga sulit dikerjakan terpisah — misalnya menyeimbangkan rasa manis, asam, dan asin dalam satu masakan. Untuk kasus seperti ini...",options:["Tetap paksakan tiap rasa dikerjakan orang berbeda tanpa mencicipi hasil keseluruhannya","Sadari bahwa bagian ini harus disesuaikan bersama-sama sambil mencicipi keseluruhan","Jangan memasak karena masalah yang bagiannya saling terkait tidak mungkin diselesaikan"],answer:1,explain:"Tidak semua masalah bisa dipecah bersih. Bila bagian-bagian saling memengaruhi kuat, sebagian penyesuaian harus dilakukan secara menyeluruh.",hint:"Bisakah kamu mengatur keasinan tanpa mencicipi rasa keseluruhan?"},
{n:62,type:"tf",micro:"Optimum bagian bukan optimum keseluruhan",q:"Benar atau Salah: Membuat tiap bagian sebaik mungkin secara terpisah selalu menghasilkan keseluruhan yang terbaik.",answer:false,explain:"Kadang tidak. Contoh: tiap penulis membuat bab terbaik versinya, tapi gaya antar bab jadi tidak nyambung. Keseluruhan butuh penyelarasan, bukan hanya bagian yang bagus.",hint:"Apakah 5 solois terhebat otomatis menjadi paduan suara terbaik?"},
{n:63,type:"mcq",micro:"Biaya koordinasi",q:"Memecah tugas menjadi 20 bagian untuk 20 orang bisa menjadi tidak efisien karena...",options:["Dua puluh orang bekerja lebih lambat dari satu orang, berapa pun besarnya tugas yang dibagi","Tidak mungkin membagi tugas menjadi 20 bagian, karena tiap tugas hanya bisa dibagi paling banyak lima","Waktu dan usaha untuk mengoordinasikan 20 orang bisa lebih besar daripada waktu yang dihemat"],answer:2,explain:"Setiap pembagian menambah 'biaya koordinasi' (komunikasi, penyatuan hasil). Pada titik tertentu, menambah orang justru memperlambat.",hint:"Apakah menambah orang selalu mempercepat pekerjaan?"},
{n:64,type:"mcq",micro:"Kesalahan: bagian tidak setara",q:"Kelompok membagi 12 artikel menjadi: 3 orang dapat 1 artikel, 1 orang dapat 9 artikel. Kesalahan dekomposisinya:",options:["Bagian tidak seimbang; satu orang kelebihan beban dan kemungkinan besar menjadi penghambat","Terlalu banyak bagian yang dibuat, padahal masalah tidak boleh dibagi menjadi lebih dari dua bagian","Tidak ada kesalahan, yang penting seluruh artikel sudah terbagi habis walaupun jumlahnya tidak seimbang"],answer:0,explain:"Pembagian yang timpang membuat satu bagian menjadi jalur kritis yang sangat panjang, memperlambat semua.",hint:"Siapa yang akan menyebabkan seluruh tugas terlambat?"},
{n:65,type:"mcq",micro:"Kesalahan: melupakan penyatuan",q:"Tiga orang mengerjakan tiga bagian presentasi secara terpisah dan menggabungkannya 5 menit sebelum tampil. Risiko utama:",options:["Tidak ada risiko, karena tiap orang sudah memahami bagiannya dan hasil akhirnya otomatis menyatu","Gaya, urutan, dan sambungan antar bagian belum sempat diselaraskan sehingga presentasi terasa terputus-putus","Presentasi menjadi terlalu rapi dan seragam, sehingga penonton cepat bosan mendengarkan ketiganya"],answer:1,explain:"Dekomposisi tanpa cukup waktu untuk penyatuan dan latihan gabungan sering menghasilkan produk yang 'kelihatan jahitannya'.",hint:"Kapan bagian-bagian itu diperiksa sebagai satu kesatuan?"},
{n:66,type:"mcq",micro:"Dekomposisi berlebihan pada masalah sederhana",q:"Untuk 'membalas satu pesan singkat dari teman', membuat pohon masalah 3 tingkat adalah...",options:["Wajib dilakukan untuk setiap masalah, sekecil apa pun itu","Langkah yang bijak karena semua masalah perlu direncanakan dulu","Berlebihan; masalah sekecil ini cukup langsung dikerjakan"],answer:2,explain:"Dekomposisi adalah alat untuk masalah yang cukup besar atau rumit. Memaksakannya pada hal sepele hanya memperlambat.",hint:"Apakah setiap keputusan kecil butuh diagram?"},
{n:67,type:"tf",micro:"Sub-masalah bisa saling bertentangan",q:"Benar atau Salah: Kadang menyelesaikan satu sub-masalah dengan cara tertentu membuat sub-masalah lain lebih sulit, sehingga perlu kompromi antar bagian.",answer:true,explain:"Contoh: 'buat panggung besar' (sub-masalah dekorasi) berbenturan dengan 'sisakan ruang untuk kursi penonton' (sub-masalah tempat duduk). Bagian-bagian perlu ditimbang bersama.",hint:"Bisakah dua bagian menarik ke arah yang berlawanan?"},
{n:68,type:"mcq",micro:"Menahan diri memecah terlalu dini",q:"Sebelum memecah masalah, kadang berguna memahaminya secara utuh dulu karena...",options:["Memahami keseluruhan membantu memilih cara pemecahan yang tepat dan mengenali bagian yang saling terkait","Memahami keseluruhan masalah tidak berguna, karena pemecahan bisa langsung dimulai tanpa berpikir","Pemecahan harus menjadi langkah pertama, tanpa perlu memahami masalahnya secara utuh lebih dahulu"],answer:0,explain:"Melihat gambaran besar dulu membantu memilih 'sumbu' pemecahan dan menghindari membelah bagian yang sebenarnya satu kesatuan.",hint:"Bagaimana kamu tahu di mana harus 'memotong' kalau belum melihat keseluruhannya?"},
{n:69,type:"mcq",micro:"Bagian yang tergantung pada hasil bagian lain",q:"Sub-tugas 'menentukan jumlah kursi' bergantung pada hasil sub-tugas 'memperkirakan jumlah penonton'. Kalau perkiraan penonton berubah di tengah jalan...",options:["Sub-tugas kursi tidak terpengaruh, karena kursi tak terkait penonton","Sub-tugas kursi (dan yang bergantung padanya) perlu ditinjau ulang","Seluruh proyek harus dimulai ulang walau hanya satu perkiraan berubah"],answer:1,explain:"Perubahan pada satu bagian merambat ke bagian yang bergantung padanya. Memetakan ketergantungan membantu tahu apa yang harus diperbarui.",hint:"Bagian mana yang 'memakai' hasil dari bagian yang berubah?"},
{n:70,type:"order",micro:"Menangani sub-masalah yang gagal",q:"Salah satu sub-tugas ternyata tidak bisa diselesaikan sesuai rencana. Urutkan respons yang masuk akal.",items:["Kenali bahwa sub-tugas ini bermasalah dan seberapa penting ia bagi hasil akhir","Periksa bagian lain mana yang bergantung padanya","Cari cara alternatif menyelesaikan sub-tugas, atau sesuaikan tujuan bagian itu","Perbarui rencana dan beri tahu anggota yang terdampak"],answer:[0,1,2,3],explain:"Kenali masalah → petakan dampaknya ke bagian lain → cari alternatif → perbarui rencana dan komunikasikan.",hint:"Sebelum mencari solusi, pahami dulu seberapa besar dampaknya."},
{n:71,type:"mcq",micro:"Dekomposisi menyembunyikan gambaran besar",q:"Bahaya terlalu fokus pada sub-tugas kecil selama berminggu-minggu adalah...",options:["Menjadi terlalu efisien sehingga pekerjaan selesai sebelum waktunya habis","Terlalu cepat bosan sehingga anggota tim ingin berpindah ke proyek yang lain","Kehilangan pandangan apakah gabungan semua bagian masih menuju tujuan yang benar"],answer:2,explain:"Sesekali 'menjauh' untuk melihat keseluruhan memastikan bagian-bagian masih menyatu ke arah yang diinginkan.",hint:"Bisa saja tiap bagian rapi, tapi seluruhnya menyimpang dari tujuan awal — bagaimana kamu tahu?"},
{n:72,type:"mcq",micro:"Kapan berhenti memecah",q:"Kamu sebaiknya berhenti memecah sebuah bagian ketika...",options:["Bagian itu sudah cukup jelas sehingga kamu tahu tindakan pertamanya dan bisa memperkirakan usahanya","Kamu sudah bosan mengerjakannya dan ingin segera pindah ke bagian yang lain di daftar","Bagian itu punya nama yang bagus dan terdengar meyakinkan bagi semua anggota kelompok"],answer:0,explain:"Berhenti saat bagian sudah 'bisa dieksekusi': jelas apa langkahnya dan kira-kira berapa lama.",hint:"Apa dua tanda bahwa sebuah bagian tidak perlu dipecah lagi?"},
{n:73,type:"tf",micro:"Dekomposisi berbeda oleh orang berbeda",q:"Benar atau Salah: Untuk setiap masalah hanya ada satu cara pemecahan yang benar, jadi dua orang seharusnya selalu menghasilkan pohon masalah yang sama.",answer:false,explain:"Tidak ada satu-satunya pemecahan yang benar. Dua orang bisa memecah masalah yang sama secara berbeda dan keduanya masuk akal, asalkan lengkap, tidak banyak tumpang tindih, dan mengarah ke tindakan.",hint:"Apakah hanya ada satu cara memotong sebuah kue?"},
{n:74,type:"mcq",micro:"Ketergantungan tersembunyi",q:"Dua sub-tugas tampak bebas, tapi keduanya sama-sama butuh dikerjakan di satu-satunya komputer kelas. Ini adalah ketergantungan lewat...",options:["Nama tugas yang mirip","Sumber daya bersama yang terbatas","Kebetulan yang tidak penting"],answer:1,explain:"Bagian bisa saling menghambat bukan karena butuh hasil satu sama lain, tapi karena berebut sumber daya yang sama (alat, ruang, orang).",hint:"Apa yang tidak bisa dipakai dua tugas sekaligus di sini?"},
{n:75,type:"mcq",micro:"Menyeimbangkan rincian dan kecepatan",q:"Untuk tugas dengan tenggat sangat dekat, pendekatan dekomposisi yang masuk akal:",options:["Habiskan seluruh waktu untuk membuat rencana rinci, sehingga pekerjaan tidak sempat dimulai","Jangan memecah, lalu kerjakan asal jadi supaya tenggatnya terasa tidak menekan","Pecah secukupnya untuk membagi kerja dan mengenali langkah kritis, lalu segera mulai"],answer:2,explain:"Di bawah tekanan waktu, dekomposisi tetap berguna tapi harus ringkas: cukup untuk membagi dan mengurutkan, tidak lebih.",hint:"Berapa banyak perencanaan yang sepadan kalau waktunya tinggal sedikit?"},
{n:76,type:"mcq",micro:"Bagian yang sebaiknya digabung",q:"Kamu memecah 'membuat sampul buku' menjadi 'menggambar garis tepi' dan 'mewarnai garis tepi'. Ini mungkin...",options:["Terlalu halus — kedua langkah ini lebih baik dianggap satu tugas kecil","Wajib dipisah karena menggambar dan mewarnai dikerjakan oleh orang berbeda","Pemecahan yang berguna karena setiap langkah kecil harus dipisah sedetail mungkin"],answer:0,explain:"Bila dua langkah selalu dikerjakan berurutan oleh orang yang sama dalam hitungan menit, menggabungkannya membuat rencana lebih ringkas.",hint:"Adakah gunanya memisahkan dua langkah yang tak terpisahkan dalam praktik?"},
{n:77,type:"tf",micro:"Dekomposisi membantu menemukan yang tidak kita ketahui",q:"Benar atau Salah: Proses memecah masalah sering memunculkan pertanyaan 'kita belum tahu bagaimana melakukan bagian ini', yang berguna diketahui lebih awal.",answer:true,explain:"Dekomposisi menyoroti bagian yang belum jelas caranya — memberi kesempatan untuk belajar atau mencari bantuan sebelum terlambat.",hint:"Kapan lebih baik menyadari 'aku tidak tahu cara ini' — di awal atau di malam sebelum tenggat?"},
{n:78,type:"mcq",micro:"Dekomposisi masalah yang tidak jelas tujuannya",q:"Kalau tujuan masalah masih kabur ('bikin kelas lebih asik'), langkah paling tepat sebelum memecah:",options:["Kerjakan yang terpikir lebih dulu sambil berharap kelas jadi asik","Perjelas dulu apa arti 'lebih asik' dalam bentuk yang bisa diamati","Langsung buat 50 sub-tugas tanpa tahu apa arti 'lebih asik'"],answer:1,explain:"Dekomposisi butuh tujuan yang cukup jelas. Tanpa itu, sub-tugasnya akan ikut kabur.",hint:"Bisakah kamu memecah perjalanan kalau tidak tahu tujuannya?"},
{n:79,type:"mcq",micro:"Meninjau pohon masalah",q:"Setelah membuat pohon masalah, dua pertanyaan pemeriksa yang baik:",options:["'Apakah pohonnya terlihat rapi dan indah?' dan 'Apakah warna tulisan pada tiap cabangnya sudah bagus?'","'Apakah cabangnya sudah banyak sekali?' dan 'Apakah nama tiap cabangnya terdengar keren dan menarik?'","'Apakah gabungan semua cabang menutupi seluruh masalah?' dan 'Apakah ada cabang yang tumpang tindih?'"],answer:2,explain:"Dua uji kualitas: lengkap (menutupi semua) dan tidak tumpang tindih (tiap bagian jelas milik satu cabang).",hint:"Ingat dua syarat pemecahan yang baik dari fase sebelumnya."},
{n:80,type:"open",micro:"Kritik sebuah dekomposisi",q:"Seorang teman memecah 'mengurangi keterlambatan siswa' menjadi: (a) beri hukuman, (b) siswa yang terlambat kurang disiplin, (c) buat gerbang lebih besar. Jelaskan minimal dua kelemahan dekomposisi ini dan tawarkan sumbu pemecahan yang lebih baik.",explain:"Jawaban baik mengenali bahwa item bukan sub-masalah sejati (ada yang berupa tuduhan atau solusi), menilai kelengkapan, dan menawarkan sumbu yang lebih bisa ditindaklanjuti.",hint:"Periksa: apakah tiap item benar-benar 'bagian dari masalah', dan apakah kumpulannya lengkap?",sample:"Kelemahan: (1) (b) bukan sub-masalah melainkan tuduhan/penyebab yang belum terbukti — bukan bagian yang bisa 'dikerjakan'. (2) (a) dan (c) sudah melompat ke solusi, bukan memecah masalah; (c) juga tidak jelas berhubungan. (3) Tidak lengkap: tidak menyentuh penyebab seperti transportasi, antre di pintu, atau jam tidur. Sumbu lebih baik — berdasarkan tahap perjalanan siswa: di rumah (bangun, sarapan) / di jalan (transport, jarak) / di gerbang (antre, pemeriksaan). Tiap tahap bisa diamati dan diperbaiki."},
{n:81,type:"mcq",micro:"Memecah masalah dengan banyak pihak",q:"Masalah: 'Perpustakaan sekolah kurang dimanfaatkan.' Sumbu pemecahan berdasarkan PIHAK menghasilkan sub-masalah: siswa, guru, pustakawan, orang tua. Keunggulan sumbu ini:",options:["Tiap pihak punya hambatan dan peran berbeda, sehingga solusinya bisa disesuaikan per kelompok","Membuat masalah terdengar lebih besar dan menakutkan sehingga orang enggan menyentuhnya","Pembagian pihak hanya menambah panjang daftar kerja dan tidak membantu merancang solusi"],answer:0,explain:"Ketika sebuah masalah melibatkan banyak pihak dengan kepentingan berbeda, memecah berdasarkan pihak memungkinkan solusi yang tepat sasaran untuk masing-masing.",hint:"Apakah hambatan siswa sama dengan hambatan guru?"},
{n:82,type:"mcq",micro:"Dekomposisi bertingkat pada proyek nyata",q:"Panitia bazar memecah: Keuangan → (modal awal, pencatatan pemasukan, pembagian hasil). 'Pencatatan pemasukan' masih terasa besar. Pemecahan tingkat berikutnya yang masuk akal:",options:["Nama bank, jenis rekening, besar bunga tabungan, dan syarat membuka rekening baru panitia","Format buku kas, siapa yang mencatat tiap sesi, cara menyetor uang ke bendahara, waktu rekap harian","Warna sampul buku kas, jenis pulpen, dan merek kalkulator yang dipakai bendahara bazar"],answer:1,explain:"Sub-masalah yang masih kabur dipecah lagi menjadi tugas konkret: alat, orang, prosedur, jadwal.",hint:"Ubah 'pencatatan pemasukan' menjadi langkah nyata yang bisa dikerjakan seseorang."},
{n:83,type:"tf",micro:"Bagian paralel butuh titik sinkronisasi",q:"Benar atau Salah: Ketika beberapa tim mengerjakan bagian secara paralel, paling efisien membiarkan mereka bekerja terpisah tanpa pertemuan sampai semua bagian selesai.",answer:false,explain:"Menyatukan hasil hanya di akhir sering memunculkan kejutan buruk. Titik sinkronisasi berkala membuat masalah antar bagian ketahuan lebih awal, saat masih murah diperbaiki.",hint:"Lebih baik menemukan ketidakcocokan antar bagian setiap minggu, atau sekaligus di hari terakhir?"},
{n:84,type:"mcq",micro:"Dekomposisi masalah pribadi kompleks",q:"'Nilai rapotku turun di banyak pelajaran.' Pemecahan paling berguna:",options:["Anggap saja 'sekolah terlalu sulit untuk anak seusiaku' — lalu penyebab turunnya nilai tidak perlu diperiksa karena memang tidak bisa diubah oleh dirimu sendiri maupun orang lain","Anggap saja 'aku memang bodoh dan tidak berbakat belajar' — satu penyebab tunggal yang menjelaskan semuanya, sehingga tidak perlu memeriksa kebiasaan belajar, waktu tidur, ataupun cara mengerjakan ujian","Pisahkan per faktor: kebiasaan belajar, waktu tidur & kesehatan, gangguan/fokus, pemahaman materi tertentu, cara mengerjakan ujian — lalu periksa mana yang paling berpengaruh"],answer:2,explain:"Masalah pribadi yang besar menjadi bisa ditangani ketika dipecah menjadi faktor-faktor spesifik yang masing-masing bisa diamati dan diperbaiki.",hint:"Ubah masalah besar menjadi 4–5 faktor yang bisa kamu cek satu per satu."},
{n:85,type:"mcq",micro:"Ketika dua pemecahan bersaing",q:"Untuk 'meningkatkan kebugaran kelas', Tim A memecah berdasarkan jenis olahraga; Tim B memecah berdasarkan waktu (sebelum sekolah / istirahat / pulang). Cara memilih:",options:["Pilih yang lebih memudahkan menyusun tindakan nyata dan pembagian tanggung jawab untuk situasi kelas ini","Pilih pemecahan Tim A saja, karena jenis olahraga lebih penting daripada urutan waktunya dalam situasi kelas","Gabungkan keduanya menjadi 20 bagian kecil sekaligus tanpa melihat apakah itu memudahkan pembagian tanggung jawab"],answer:0,explain:"Beberapa pemecahan bisa sama-sama valid; pilih yang paling praktis untuk direncanakan dan dilaksanakan dalam konteks nyata.",hint:"Sumbu mana yang lebih cepat menghasilkan 'siapa melakukan apa, kapan'?"},
{n:86,type:"order",micro:"Dari masalah besar ke tindakan minggu ini",q:"Urutkan langkah mengubah masalah besar menjadi tindakan konkret untuk minggu ini.",items:["Nyatakan masalah dan tujuan yang cukup jelas","Pecah menjadi sub-masalah, lalu pecah lagi sampai ada tugas berukuran satu sesi","Pilih 2–3 tugas berdampak tinggi yang bisa selesai minggu ini","Jadwalkan tugas terpilih itu ke hari tertentu dan tentukan pelaksananya"],answer:[0,1,2,3],explain:"Perjelas → pecah dalam-dalam → pilih tugas berdampak yang muat minggu ini → jadwalkan dengan pelaksana.",hint:"Kamu baru bisa memilih tugas minggu ini setelah punya daftar tugas kecil."},
{n:87,type:"mcq",micro:"Bagian yang menghasilkan informasi",q:"Beberapa sub-tugas nilainya bukan menghasilkan produk, tapi menghasilkan informasi — misalnya 'survei kecil ke 10 siswa'. Sub-tugas semacam ini sebaiknya...",options:["Dihapus dari daftar karena tidak menghasilkan produk, sehingga hanya membuang waktu","Dikerjakan lebih awal, karena hasilnya bisa mengubah cara mengerjakan bagian lain","Dikerjakan paling akhir setelah bagian lain selesai, sehingga hasil survei tak sempat dipakai"],answer:1,explain:"Tugas yang mengurangi ketidakpastian paling berharga bila dikerjakan lebih dulu — hasilnya bisa menghemat usaha di bagian lain.",hint:"Kapan sebaiknya kamu mencari tahu 'apa yang sebenarnya diinginkan orang'?"},
{n:88,type:"mcq",micro:"Dekomposisi dan tanggung jawab bersama",q:"Setiap bagian sudah punya penanggung jawab, tapi 'keberhasilan proyek secara keseluruhan' adalah tanggung jawab...",options:["Bagian yang paling besar saja, sehingga anggota yang mengerjakannya juga harus mengawasi seluruh bagian lain","Tidak ada pihak khusus, karena setelah semua bagian dibagi, hasil akhirnya beres dengan sendirinya","Tetap perlu seseorang (atau tim inti) yang memantau gambaran besar dan sambungan antar bagian"],answer:2,explain:"Membagi bagian tidak menghilangkan kebutuhan akan seseorang yang menjaga keseluruhan tetap menyatu dan menuju tujuan.",hint:"Siapa yang memperhatikan 'apakah semua bagian ini benar-benar menjadi satu'?"},
{n:89,type:"tf",micro:"Dekomposisi mengubah masalah mustahil jadi mungkin",q:"Benar atau Salah: Banyak masalah yang terasa 'tidak mungkin diselesaikan' sebenarnya adalah kumpulan beberapa masalah yang masing-masing bisa diselesaikan.",answer:true,explain:"Rasa 'mustahil' sering datang dari melihat semuanya sekaligus. Dipecah, tiap bagian ternyata bisa dikerjakan.",hint:"Bagaimana orang mendaki gunung yang tinggi?"},
{n:90,type:"mcq",micro:"Menangani bagian yang membengkak",q:"Di tengah proyek, satu sub-tugas ternyata jauh lebih besar dari perkiraan dan mengancam tenggat. Respons dekomposisi yang tepat:",options:["Pecah sub-tugas besar itu lagi menjadi bagian lebih kecil, tentukan bagian minimum yang benar-benar wajib, dan pertimbangkan menunda atau menyederhanakan sisanya","Batalkan seluruh proyek sekarang juga, lalu mulai lagi dari awal dengan rencana, anggota, dan tenggat yang sepenuhnya baru supaya tidak terulang","Abaikan tenggat dan teruskan sub-tugas besar itu pelan-pelan sampai selesai, sementara bagian lain dibiarkan menunggu tanpa kepastian kapan akan dikerjakan"],answer:0,explain:"Sub-tugas yang membengkak diperlakukan seperti masalah baru: pecah lagi, pisahkan yang wajib dari yang opsional, lalu sesuaikan cakupan.",hint:"Bagian mana dari sub-tugas besar itu yang benar-benar tidak bisa ditinggalkan?"},
{n:91,type:"mcq",micro:"Dekomposisi lintas waktu untuk tujuan jangka panjang",q:"Tujuan: 'Dalam setahun, klub robotik kelas bisa ikut lomba tingkat kota.' Pemecahan yang berguna:",options:["Satu langkah besar saja: 'ikut lomba' — lalu semua anggota menunggu sampai hari perlombaan itu tiba nantinya","Bagi per triwulan: TW1 belajar dasar & rekrut anggota; TW2 bangun robot latihan; TW3 uji & perbaiki; TW4 daftar & latihan lomba","Tunggu sampai bulan lomba semakin dekat, baru mulai belajar dan membuat robot dengan cara kerja secepat mungkin"],answer:1,explain:"Tujuan jangka panjang dipecah menjadi tonggak berkala, masing-masing dengan sub-tugasnya sendiri.",hint:"Apa yang harus sudah tercapai di pertengahan tahun agar tujuan akhir realistis?"},
{n:92,type:"mcq",micro:"Bagian yang saling menguatkan",q:"Dalam proyek, sub-tugas 'membuat panduan singkat' dan 'melatih anggota baru' ternyata saling menguatkan. Implikasinya untuk perencanaan:",options:["Kerjakan keduanya secara terpisah dan acak, karena urutan tidak memengaruhi hasil akhir proyek","Buang salah satunya karena dua sub-tugas yang saling menguatkan akan membingungkan seluruh tim","Kerjakan panduan lebih dulu, lalu pakai untuk pelatihan — satu bagian membuat bagian lain lebih mudah"],answer:2,explain:"Mengenali sinergi antar bagian memungkinkan mengurutkannya agar output satu bagian menjadi masukan yang mempermudah bagian lain.",hint:"Bagian mana yang menghasilkan sesuatu yang berguna untuk bagian lainnya?"},
{n:93,type:"tf",micro:"Rencana dekomposisi adalah alat komunikasi",q:"Benar atau Salah: Pohon atau daftar sub-tugas hanya berguna bagi si pembuat rencana sendiri dan tidak membantu menjelaskan proyek kepada orang lain.",answer:false,explain:"Struktur pemecahan yang jelas justru membuat orang lain — guru, orang tua, anggota baru — langsung memahami cakupan proyek, pembagian tugas, dan status kemajuannya.",hint:"Bagaimana cara tercepat menunjukkan 'inilah semua yang perlu dikerjakan dan sudah sampai mana kami'?"},
{n:94,type:"open",micro:"Dekomposisi masalah dunia nyata",q:"Pilih masalah nyata berskala sedang di sekolah/lingkunganmu. Lakukan: (1) nyatakan masalah + tujuan terukur, (2) pilih SATU sumbu pemecahan dan beri alasan, (3) daftar 4–6 sub-masalah, (4) pecah salah satu sub-masalah menjadi tugas berukuran satu sesi, (5) tandai ketergantungan utama antar sub-masalah.",explain:"Jawaban baik: tujuan terukur, alasan pemilihan sumbu, sub-masalah yang lengkap & tidak tumpang tindih, satu sub-masalah dipecah sampai bisa dikerjakan, dan ketergantungan yang benar.",hint:"Pilih sumbu yang membuat tiap bagian bisa diamati dan diperbaiki secara terpisah.",sample:"Contoh — Masalah: koridor lantai 1 macet 3–4 menit tiap pergantian jam; tujuan: waktu perpindahan < 1,5 menit tanpa berdesakan. Sumbu: berdasarkan TITIK di sepanjang alur perpindahan (keluar kelas → koridor → tangga → kelas berikutnya), karena kemacetan bisa terjadi di titik mana pun dan tiap titik punya solusi berbeda. Sub-masalah: (a) waktu keluar kelas, (b) lebar & rute koridor, (c) kapasitas tangga, (d) perilaku (berhenti mengobrol di tengah jalan), (e) jadwal (semua pindah pada detik yang sama). Pecah (e): kumpulkan jadwal semua kelas lantai 1; identifikasi 2 pasang kelas yang bertukar arah berlawanan; usulkan selisih bel 60 detik untuk 2 kelas; ujicoba 1 minggu; ukur ulang. Ketergantungan: solusi (e) harus diuji sebelum menilai apakah (b) dan (c) masih bermasalah."},
{n:95,type:"mcq",micro:"Menilai kelengkapan dengan uji 'sisa'",q:"Cara cepat memeriksa apakah daftar sub-masalahmu lengkap:",options:["Bayangkan semua sub-masalah selesai sempurna — apakah masalah utama pasti beres? Kalau tidak, ada yang kurang","Hitung jumlah sub-masalahnya saja; kalau lebih dari lima, berarti daftar itu sudah lengkap dan siap","Tanyakan apakah daftar itu terlihat panjang dan rapi di kertas; kalau ya, berarti daftar itu sudah lengkap"],answer:0,explain:"Uji 'andai semua bagian selesai': bila masalah utama tetap belum tuntas, berarti ada sub-masalah yang belum masuk daftar.",hint:"Jumlahkan semua bagian secara imajinatif — apakah hasilnya masalah utuh?"},
{n:96,type:"mcq",micro:"Dekomposisi dan pembelajaran",q:"Setelah proyek selesai, meninjau pohon masalah awal dibanding kenyataan berguna untuk...",options:["Tidak berguna, karena proyek sudah selesai dan pohon masalah yang lama tidak dipakai lagi oleh pihak mana pun di sekolah","Belajar: bagian mana yang lebih besar/kecil dari dugaan, ketergantungan apa yang terlewat — supaya dekomposisi berikutnya lebih baik","Menyalahkan orang yang dulu salah memperkirakan ukuran tiap bagian, supaya lain kali ia tidak berani lagi ikut memecah masalah"],answer:1,explain:"Membandingkan rencana pemecahan dengan hasil nyata membangun kemampuan memperkirakan dan memecah masalah dari waktu ke waktu.",hint:"Apa yang bisa kamu bawa ke proyek berikutnya?"},
{n:97,type:"tf",micro:"Dekomposisi cocok untuk masalah dan peluang",q:"Benar atau Salah: Teknik memecah menjadi bagian kecil juga berguna untuk mengejar peluang atau tujuan positif, bukan hanya untuk memperbaiki sesuatu yang rusak.",answer:true,explain:"Merancang acara, membangun keterampilan baru, atau memulai usaha kecil semuanya diuntungkan oleh dekomposisi, sama seperti memperbaiki masalah.",hint:"Apakah 'belajar bermain gitar' bisa dipecah menjadi bagian?"},
{n:98,type:"mcq",micro:"Sub-masalah sebagai unit yang bisa dipindahtangankan",q:"Anggota yang mengerjakan satu sub-tugas tiba-tiba sakit seminggu. Karena tugas sudah dipecah dengan baik...",options:["Seluruh proyek berhenti total sampai anggota itu kembali sehat, karena tidak ada orang lain yang paham tugasnya","Tidak banyak pilihan selain menunggu, sebab bagian itu hanya bisa dikerjakan oleh satu orang itu","Sub-tugasnya jelas batas dan statusnya, sehingga bisa diserahkan ke orang lain tanpa mengganggu bagian lain"],answer:2,explain:"Dekomposisi yang rapi membuat tiap bagian menjadi 'paket' yang bisa dialihkan, dengan batas dan status yang jelas.",hint:"Apa yang membuat sebuah tugas mudah 'dioper' ke orang lain?"},
{n:99,type:"mcq",micro:"Ringkasan: nilai dekomposisi",q:"Rangkuman paling tepat tentang mengapa memecah masalah berguna:",options:["Mengubah masalah besar yang membingungkan menjadi kumpulan tugas kecil yang jelas, bisa dibagi, dijadwalkan, dan dilacak — sambil tetap menjaga pandangan ke keseluruhan","Menghilangkan kebutuhan untuk bekerja sama, karena begitu masalah besar dipecah maka semua bagiannya akan selesai dengan sendirinya tanpa perlu dikerjakan","Membuat masalah terdengar rumit dan sangat mengesankan di depan orang lain, sehingga kita dianggap pintar, sibuk, dan tidak perlu dibantu orang lain"],answer:0,explain:"Dekomposisi membuat masalah bisa dikelola: dipahami, dibagi, dijadwalkan, dan dipantau — dengan penyatuan kembali dan pandangan keseluruhan sebagai pelengkapnya.",hint:"Gabungkan: jelas + bisa dibagi + bisa dilacak + tetap lihat keseluruhan."},
{n:100,type:"open",micro:"Kapstone: pecah, kerjakan, tinjau",q:"Ambil satu tujuan pribadi berjangka ~1 bulan (misalnya 'membaca 4 buku', 'bisa 20 push-up', 'membuat blog kelas'). Lakukan seluruh proses: (1) tujuan terukur + tenggat, (2) pohon masalah 2 tingkat (min. 3 cabang, satu cabang dipecah lagi), (3) perkiraan waktu tiap tugas terkecil, (4) urutan & ketergantungan, (5) rencana mingguan (tugas apa di minggu ke berapa), (6) satu risiko terbesar + rencana cadangannya.",explain:"Kapstone menggabungkan semuanya: tujuan terukur, dekomposisi bertingkat, perkiraan, ketergantungan, penjadwalan, dan perencanaan risiko.",hint:"Kerjakan keenam bagian berurutan; tingkat terkecil pohon harus berupa latihan/tugas nyata harian.",sample:"Contoh — Tujuan: dalam 4 minggu bisa memainkan satu lagu penuh di keyboard, tanpa berhenti, tempo lambat. (2) Cabang: A. Dasar teknik (posisi tangan, tangga nada C, latihan jari) B. Lagu bagian per bagian (bait, reff, jembatan) — dipecah: B1 bait tangan kanan, B2 bait tangan kiri, B3 gabung bait, B4 reff kanan, B5 reff kiri, B6 gabung reff, B7 sambung bait+reff. C. Latihan rutin & rekam (jadwal harian, rekam tiap akhir minggu untuk cek). (3) tiap tugas B: ~20–30 menit/hari beberapa hari. (4) A sebelum B; B1,B2 sebelum B3; dst.; C sepanjang proyek. (5) Mgg1: A + B1–B3. Mgg2: B4–B6. Mgg3: B7 + main lambat penuh. Mgg4: perbaiki bagian tersendat + naikkan sedikit tempo. (6) Risiko: bagian reff tangan kiri terlalu sulit → cadangan: sederhanakan menjadi nada dasar saja, atau perpanjang jadwal reff 3 hari dengan memangkas latihan tangga nada."},
];
